from httpbin.core import app
client = app.test_client()

def test_patch_custom_header_reflected_in_headers_field():
    r = client.patch(
        '/patch',
        headers={'X-Test-Header': 'sentinel42'}
    )
    assert r.status_code == 200
    body = r.get_json()
    assert 'headers' in body
    headers_lower = {k.lower(): v for k, v in body['headers'].items()}
    assert headers_lower.get('x-test-header') == 'sentinel42'

test_patch_custom_header_reflected_in_headers_field()
